// Parse input from AI agent
const raw = $input.all()[0].json.input || $input.all()[0].json.query || '{}';
const { date, time_slot, email } = typeof raw === 'string' ? JSON.parse(raw) : raw;

const SHEET_ID = process.env.BOOKING_SHEET_ID;
const ACCESS_TOKEN = process.env.GOOGLE_ACCESS_TOKEN;

if (!SHEET_ID || !ACCESS_TOKEN) {
  throw new Error('BOOKING_SHEET_ID and GOOGLE_ACCESS_TOKEN must be set in n8n environment variables');
}

// Fetch all rows from Bookings sheet
const res = await fetch(
  `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/Bookings!A:T`,
  { headers: { Authorization: `Bearer ${ACCESS_TOKEN}` } }
);
const data = await res.json();

if (!data.values || data.values.length < 2) {
  return JSON.stringify({ available: true, bookingCount: 0, isDuplicate: false });
}

const headers = data.values[0];
const rows    = data.values.slice(1);

const dateIdx   = headers.indexOf('Date');
const timeIdx   = headers.indexOf('Time_Slot');
const statusIdx = headers.indexOf('Status');
const emailIdx  = headers.indexOf('Email');

const bookedRows = rows.filter(
  r => r[dateIdx] === date && r[timeIdx] === time_slot && r[statusIdx] === 'BOOKED'
);

const isDuplicate  = bookedRows.some(r => r[emailIdx] === email);
const bookingCount = bookedRows.length;

return JSON.stringify({
  available:    bookingCount < 2,
  bookingCount,
  isDuplicate
});

const raw = $input.all()[0].json.input || $input.all()[0].json.query || '{}';
const p = typeof raw === 'string' ? JSON.parse(raw) : raw;

const ACCESS_TOKEN = process.env.GOOGLE_ACCESS_TOKEN;
const CALENDAR_ID  = process.env.GOOGLE_CALENDAR_ID || 'primary';

if (!ACCESS_TOKEN) throw new Error('GOOGLE_ACCESS_TOKEN must be set in n8n environment variables');

// Calculate duration by plan
const durations = { Basic: 30, Standard: 60, Premium: 90, Elite: 120 };
const duration  = durations[p.plan] || 60;

const [h, m]  = p.time_slot.split(':').map(Number);
const endTotal = h * 60 + m + duration;
const endH     = String(Math.floor(endTotal / 60)).padStart(2, '0');
const endM     = String(endTotal % 60).padStart(2, '0');

const start = `${p.date}T${p.time_slot}:00`;
const end   = `${p.date}T${endH}:${endM}:00`;

const event = {
  summary: `Car Wash - ${p.client_name} - ${p.plan}`,
  description: [
    `Booking ID: ${p.bookingId}`,
    `Client: ${p.client_name}`,
    `Phone: ${p.phone}`,
    `Email: ${p.email}`,
    `Vehicle: ${p.vehicle_type} - ${p.vehicle_model}`,
    `Plan: ${p.plan}`,
    `Price: €${p.price}`,
    `Pet Hair Removal: ${p.pet_hair_removal}`,
    `Flexible Timing: ${p.flexible_timing}`,
  ].join('\n'),
  start: { dateTime: `${start}+01:00`, timeZone: 'Europe/Rome' },
  end:   { dateTime: `${end}+01:00`,   timeZone: 'Europe/Rome' },
};

const res = await fetch(
  `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(CALENDAR_ID)}/events`,
  {
    method:  'POST',
    headers: { Authorization: `Bearer ${ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
    body:    JSON.stringify(event),
  }
);
const created = await res.json();

if (!created.id) throw new Error(`Calendar API error: ${JSON.stringify(created)}`);

return JSON.stringify({ calendarEventId: created.id, calendarLink: created.htmlLink });

const raw = $input.all()[0].json.input || $input.all()[0].json.query || '{}';
const p = typeof raw === 'string' ? JSON.parse(raw) : raw;

const SHEET_ID    = process.env.BOOKING_SHEET_ID;
const ACCESS_TOKEN = process.env.GOOGLE_ACCESS_TOKEN;

if (!SHEET_ID || !ACCESS_TOKEN) throw new Error('BOOKING_SHEET_ID and GOOGLE_ACCESS_TOKEN must be set');

// Row must match sheet column order exactly
const row = [
  p.Booking_ID         || '',
  p.Client_Name        || '',
  p.Phone              || '',
  p.Email              || '',
  p.Vehicle_Type       || '',
  p.Vehicle_Model      || '',
  p.Plan               || '',
  p.Price              || '',
  p.Date               || '',
  p.Time_Slot          || '',
  p.Status             || 'BOOKED',
  p.Last_Action        || 'BOOKED',
  p.Pet_Hair_Removal   || 'false',
  p.Flexible_Timing    || 'false',
  p.Original_Date      || '',
  p.Original_Time_Slot || '',
  p.Created_At         || '',
  p.Updated_At         || '',
  p.Calendar_Event_ID  || '',
  p.Cancel_Reason      || '',
];

const res = await fetch(
  `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/Bookings!A1:T1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,
  {
    method:  'POST',
    headers: { Authorization: `Bearer ${ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
    body:    JSON.stringify({ values: [row] }),
  }
);
const result = await res.json();

if (result.error) throw new Error(`Sheets API error: ${JSON.stringify(result.error)}`);

return JSON.stringify({ success: true, updatedRange: result.updates?.updatedRange });

const raw = $input.all()[0].json.input || $input.all()[0].json.query || '{}';
const { to_email, subject, html_body } = typeof raw === 'string' ? JSON.parse(raw) : raw;

const ACCESS_TOKEN  = process.env.GOOGLE_ACCESS_TOKEN;
const FROM_EMAIL    = process.env.CARWASHER_EMAIL || 'Autolavaggio04012@gmail.com';

if (!ACCESS_TOKEN) throw new Error('GOOGLE_ACCESS_TOKEN must be set in n8n environment variables');
if (!to_email || !subject || !html_body) throw new Error('to_email, subject, and html_body are all required');
if (!html_body.trim().startsWith('<html')) throw new Error('html_body must be complete HTML starting with <html>');

// Build RFC 2822 email message
const message = [
  `From: Autolavaggio La Palma <${FROM_EMAIL}>`,
  `To: ${to_email}`,
  `Subject: ${subject}`,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=UTF-8',
  '',
  html_body,
].join('\r\n');

// Base64url encode
const encoded = btoa(unescape(encodeURIComponent(message)))
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const res = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
  method:  'POST',
  headers: { Authorization: `Bearer ${ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
  body:    JSON.stringify({ raw: encoded }),
});
const result = await res.json();

if (result.error) throw new Error(`Gmail API error: ${JSON.stringify(result.error)}`);

return JSON.stringify({ success: true, messageId: result.id });

